@register.simple_tag(name='icon')
def render_icon(name, css_class='h-5 w-5', stroke_width='1.5'):
    path = ICONS.get(name)
    if not path:
        return ''
    return mark_safe(
        f'<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" '
        f'stroke-width="{escape(stroke_width)}" stroke="currentColor" '
        f'class="{escape(css_class)}" aria-hidden="true">{path}</svg>'
    )
